/* Generated by equipe-design emit — do not edit by hand; change the tokens and emit again. */
/* Light is the default. Dark follows prefers-color-scheme and can be forced with <html data-theme="dark|light">. */
:root {
  color-scheme: light dark;
  /* color */
  --acme-color-background: #ffffff;
  --acme-color-surface: #f7f7f7;
  --acme-color-raised: #fafafa;
  --acme-color-text: #1a1a1a;
  --acme-color-muted-text: #717171;
  --acme-color-primary: #2b2b2b;
  --acme-color-on-primary: #ffffff;
  --acme-color-secondary: #f1f1f1;
  --acme-color-accent: #0f766e;
  --acme-color-border: #e1e1e1;
  --acme-color-border-strong: #818181;
  --acme-color-ring: #2b2b2b;
  --acme-color-destructive: #c62828;
  --acme-color-success: #1b7a43;
  --acme-color-warning: #8f5b00;

  /* font */
  --acme-font-family-sans: 'Hanken Grotesk', Pretendard, 'Noto Sans KR', sans-serif;
  --acme-font-family-mono: 'JetBrains Mono', ui-monospace, monospace;
  --acme-font-weight-regular: 400;
  --acme-font-weight-semibold: 600;

  /* space */
  --acme-space-1: 2px;
  --acme-space-2: 4px;
  --acme-space-3: 8px;
  --acme-space-4: 12px;
  --acme-space-5: 16px;
  --acme-space-6: 24px;
  --acme-space-7: 32px;
  --acme-space-8: 48px;

  /* radius */
  --acme-radius-sm: 4px;
  --acme-radius-md: 6px;
  --acme-radius-lg: 10px;
  --acme-radius-full: 9999px;

  /* shadow */
  --acme-shadow-1: 0px 4px 14px 0px #0000001a;

  /* motion */
  --acme-duration-fast: 140ms;
  --acme-duration-base: 240ms;
  --acme-duration-slow: 400ms;

  /* motion */
  --acme-easing-standard: cubic-bezier(0.4, 0, 0.2, 1);

  /* type roles: weight size/line-height family */
  --acme-type-display: 600 40px/1.25 var(--acme-font-family-sans);
  --acme-type-display-tracking: -0.01em;
  --acme-type-h1: 600 33px/1.25 var(--acme-font-family-sans);
  --acme-type-h1-tracking: -0.01em;
  --acme-type-h2: 600 28px/1.25 var(--acme-font-family-sans);
  --acme-type-h2-tracking: -0.01em;
  --acme-type-h3: 600 23px/1.25 var(--acme-font-family-sans);
  --acme-type-h3-tracking: -0.01em;
  --acme-type-body: 400 16px/1.6 var(--acme-font-family-sans);
  --acme-type-body-tracking: 0em;
  --acme-type-small: 400 13px/1.6 var(--acme-font-family-sans);
  --acme-type-small-tracking: 0em;
  --acme-type-mono: 400 13px/1.6 var(--acme-font-family-mono);
  --acme-type-mono-tracking: 0em;
}

@media (prefers-color-scheme: dark) {
  :root:not([data-theme="light"]) {
    --acme-color-background: #111113;
    --acme-color-surface: #1d1d1f;
    --acme-color-raised: #29292b;
    --acme-color-text: #eeeeee;
    --acme-color-muted-text: #9a9a9b;
    --acme-color-primary: #f2f2f2;
    --acme-color-on-primary: #000000;
    --acme-color-secondary: #26262a;
    --acme-color-accent: #83b6b0;
    --acme-color-border: #2e2e2f;
    --acme-color-border-strong: #8b8b8b;
    --acme-color-ring: #f2f2f2;
    --acme-color-destructive: #ff7b72;
    --acme-color-success: #4cc38a;
    --acme-color-warning: #e8b44a;
  }
}
:root[data-theme="light"] { color-scheme: light; }
:root[data-theme="dark"] {
  color-scheme: dark;
  --acme-color-background: #111113;
  --acme-color-surface: #1d1d1f;
  --acme-color-raised: #29292b;
  --acme-color-text: #eeeeee;
  --acme-color-muted-text: #9a9a9b;
  --acme-color-primary: #f2f2f2;
  --acme-color-on-primary: #000000;
  --acme-color-secondary: #26262a;
  --acme-color-accent: #83b6b0;
  --acme-color-border: #2e2e2f;
  --acme-color-border-strong: #8b8b8b;
  --acme-color-ring: #f2f2f2;
  --acme-color-destructive: #ff7b72;
  --acme-color-success: #4cc38a;
  --acme-color-warning: #e8b44a;
}

